local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["b904e6acb14c0451"] = { "Fiori? In questa terra desolata? Se qualcuno può insegnarti a trovarli, è Mishiki, giù al ⟦Sen'jin Village=Villaggio di Sen'jin⟧, a sud.", "." },
  ["b909d5daff1892c3"] = { "Druido", "." },
  ["b90a830beeb8fc2f"] = { "Bah... Ragazzini!", "." },
  ["b9129158a2b0b051"] = { "Ah, librarsi con i grandi uccelli del cielo. Cerca Tal in cima al posatoio delle viverne. Ti indirizzerà dove devi andare.", "." },
  ["b929c0805451c591"] = { "Non ce la farò... la morte arriva...", "." },
  ["b934cd81ff1dcbaa"] = { "Bene allora, cominciamo. Più restiamo qui, più danni potrebbero fare i non morti a ⟦Hillsbrad=Colletorto⟧.", "." },
  ["b939d673eb07e008"] = { "Buone lame, asce solide. Non ho più nulla da insegnarti sulla fabbricazione delle armi, {name}. Porta il tuo orgoglio e il tuo coraggio da Kelgruk Bloodaxe: lui li forgerà nelle abilità che ti serviranno.", "." },
  ["b942f2bada62835f"] = { "La battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧ è una battaglia per le risorse. Legname, minerale, cibo... servono tutti per condurre bene una guerra.\n\nPrivare i nemici delle loro provviste vale quanto ucciderli sul campo di battaglia.", "." },
  ["b943fc6d057a01c6"] = { "Molto bene. Taglia un altro pezzo di carne da uno di questi esemplari. Mettiamo alla prova ciò che hai imparato finora, e da lì potremo proseguire.", "." },
  ["b94aaee4bd134e3a"] = { "BENE! E come dovrei procurarmi, di grazia, una boa di arcanite?", "." },
  ["b94ecc483fed1e0a"] = { "Non c'è niente che io possa insegnarti, se non forse un occhio migliore per i colori e i dettagli. Parla con Simon Tanner, laggiù: conosce molte tecniche avanzate per lavorare il cuoio.", "." },
  ["b9557bd20758387a"] = { "Cosa non darei per essere nelle pianure aperte in una giornata come questa... ma il dovere mi trattiene.", "." },
  ["b95a2ed589607960"] = { "Tornerò, a tempo debito..", "." },
  ["b961267a80835fa8"] = { "Ho perso il mio Confessor's Mantle e me ne serve uno nuovo, Al'tabim.", "." },
  ["b96e6ad9f0d9166f"] = { "Gli spiriti della natura sono forze da rispettare. Offrono grande aiuto a chi ne è degno e danno una morte rapida agli stolti.", "." },
  ["b970fabd7823f21e"] = { "Atten-ti! Tutto il materiale bellico per ⟦Ahn'Qiraj=Ahn'qiraj⟧ è stato contato ed è in viaggio verso la ⟦Cenarion Hold=Fortezza Cenariana⟧, <signore/signora>! Mi dicono che l'ultima parte dovrebbe arrivare in meno di un giorno. Una volta fatto, e quando qualcuno suonerà quel gong laggiù per aprire i cancelli, vi garantisco che daremo a quegli insetti una battaglia coi fiocchi!", "." },
  ["b9858cd82ee93ab4"] = { "Non è stata colpa sua, {name}. Diglielo...", "." },
  ["b9866b161153e3a7"] = { "Bottega aperta!", "." },
  ["b98875311a6f49d0"] = { "Credo che Aldwin Laughlin sia ancora il maestro di gilda residente di ⟦Stormwind=Roccavento⟧. Cerca la sua residenza sulla sinistra, appena oltrepassata la porta interna di ⟦Stormwind=Roccavento⟧.", "." },
  ["b98892c26768af5d"] = { "Borgus lavorava alla ⟦Great Forge=Grande Forgia⟧, ma ho sentito che si è trasferito a ⟦Stormwind=Roccavento⟧ quando hanno finito di ricostruirla. Si dice che abbia aperto una bottega nel Dwarven District con un tale di nome Kathrum Axehand.", "." },
  ["b992f42a9945bac3"] = { "Salute, {name}. Vedo che arrivi da Orgrimmar per aiutarci. Mi fa piacere. Voglio andarmene da questa foresta dimenticata da tutti il più in fretta possibile. Preferirei di gran lunga passare il mio tempo a Orgrimmar con una buona birra.\n\nAnche se non vedo l'ora di sapere come Belgrom sia riuscito a farti venire fin qui.", "." },
  ["b9945de07516d46b"] = { "Mastro Shaw ha fatto un po' di luce sulla faccenda?", "." },
  ["b995c5dc0d0d826b"] = { "C'è un solo cacciatore qui intorno con cui ti farei parlare, ed è Grif Wildheart. Lo troverai appena fuori dalla fucina di Kharanos.", "." },
  ["b999094943281aee"] = { "Ah... il meraviglioso suono dei kodo. Adoro come fanno tremare la terra... esamina la bestia per me.", "." },
  ["b99bf28cb7b0e2fb"] = { "Grazie ancora, {name}. Ora userò questo indurio per potenziare il mio bolide!", "." },
  ["b9cbd4b6f95c95fa"] = { "Sì, sì, avanti, di' al vecchio Greatfather Winter cosa vorresti per questo Grande Inverno.\n\nOh oh oh, sbrigati.", "." },
  ["b9d064f6c850fe04"] = { "Ben <trovato/trovata>, {class}. Il mio consiglio è questo: mentre viaggi per il mondo, diffida della magia, perché brucia chi non è addestrato.", "." },
  ["b9d8626197160c6c"] = { "Come procede la caccia a Edwin VanCleef?", "." },
  ["b9db63ad6be73d4a"] = { "Le tue capacità in Cucina sono un po' troppo basse. Forse con un po' di pratica potrò insegnarti ciò che so.", "." },
  ["b9dbaa9b9ef33bb6"] = { "Ciao di nuovo, Antonio. Grazie ancora per il cappello per mia moglie. Le è piaciuto tantissimo.", "." },
  ["b9dca4c04a838e95"] = { "Sì, mio signore.", "." },
  ["b9de3732a0afa032"] = { "Beh, eccomi qui. Ed è ora di tornare tra voi...", "." },
  ["b9edb4682b074a59"] = { "Non ho mai visto niente del genere. Nessuna perdita di concentrazione o di lucidità mentre il soggetto è dominato. Che cosa le hai fatto?", "." },
  ["b9f6cf1a94a0f20c"] = { "Se vuoi seguire la via del ladro, è Syurna che cerchi. Dimora nell'⟦Cenarion Enclave=Enclave Cenariana⟧, scendendo il sentiero a spirale dentro l'albero più a occidente.", "." },
  ["b9fa9b1f944ce6c3"] = { "Argh! Cos'è stato? Non dovrebbe funzionare così!", "." },
})
